/* Edumind Academy — Pemetaan Sinyal Psikologis Anak
 * CHECKPOINT C V1.0 DEMO • Semua data fiktif; tidak untuk diagnosis atau penggunaan data anak nyata.
 * Tidak ada server/API, analitik, cookie, unggahan, atau dependensi pihak ketiga.
 */
(()=>{'use strict';
const STORAGE='edumind-pspa-demo-session-v1';
const BRAND_LOGO='data:image/png;base64,';
const DISCLAIMER='Alat bantu observasi dan pemetaan awal. Bukan alat diagnosis psikologis.';
const LONG_NOTICE='Aplikasi ini merupakan alat bantu observasi dan pemetaan awal perilaku serta kebutuhan psikologis anak. Bukan alat diagnosis psikologis. Hasil pemetaan tidak digunakan untuk menetapkan gangguan psikologis, gangguan belajar, atau kondisi klinis. Penilaian klinis menjadi kewenangan profesional yang berkualifikasi.';
const AREAS={BL:{name:'Kesulitan Belajar',short:'Belajar',color:'#4ca29a'},PR:{name:'Perilaku & Pengaturan Diri',short:'Perilaku',color:'#edb668'},ES:{name:'Emosional & Psikososial',short:'Emosi & sosial',color:'#8eade1'}};
const IND={
 BL01:'Fokus saat kegiatan',BL02:'Mudah terdistraksi',BL03:'Mengingat instruksi',BL04:'Membaca / mengeja',BL05:'Menulis',BL06:'Konsep berhitung',BL07:'Keterlibatan belajar',
 PR01:'Aktivitas / perpindahan',PR02:'Pengendalian respons',PR03:'Interaksi fisik / konflik',PR04:'Pengelolaan waktu',PR05:'Orientasi instruksi',
 ES01:'Respons emosi',ES02:'Rasa cemas dalam konteks',ES03:'Kepercayaan diri',ES04:'Relasi teman / menarik diri',ES05:'Keamanan / perundungan',ES06:'Menghindari tugas / sekolah'
};
const LABEL_STATUS={planned:'Direncanakan',ongoing:'Berjalan',review:'Perlu ditinjau',done:'Selesai'};
const MENU=[['home','Beranda','house'],['students','Data Anak','users'],['observations','Observasi','pencil'],['signals','Peta Sinyal','activity'],['supports','Pendampingan','heart'],['reports','Laporan','file'],['guides','Panduan & Edukasi','book']];
const ICONS={house:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2"/><path d="M17 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v1"/>',pencil:'<path d="M12 20h9M4 16l12-12 4 4L8 20H4z"/>',activity:'<path d="M2 12h5l3-7 4 14 3-7h5"/>',heart:'<path d="M20.8 4.6a5.3 5.3 0 0 0-7.5 0L12 5.9l-1.3-1.3a5.3 5.3 0 0 0-7.5 7.5L12 21l8.8-8.9a5.3 5.3 0 0 0 0-7.5Z"/>',file:'<path d="M6 2h8l5 5v15H6z"/><path d="M14 2v5h5M9 12h7M9 16h7"/>',book:'<path d="M3 5a3 3 0 0 1 3-3h14v19H6a3 3 0 0 1-3-3zM3 18a3 3 0 0 1 3-3h14"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>'};
function svg(name){return '<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">'+(ICONS[name]||ICONS.activity)+'</svg>'}
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function fdate(d){if(!d)return 'Tidak ditentukan';const parts=String(d).split('-');return parts.length===3?`${parts[2]}/${parts[1]}/${parts[0]}`:String(d)}
function iso(d=new Date()){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function dayAgo(n){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-n);return iso(d)}
function dayAhead(n){return dayAgo(-n)}
function uid(prefix){return prefix+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,7).toUpperCase()}
function escapeCsv(v){const s=String(v??'').replace(/^[=+@\-\t\r]/,x=>'\''+x);return '"'+s.replace(/"/g,'""')+'"'}
function child(code,cls){return {id:code,code,klass:cls,strength:'Memiliki minat dan kemampuan yang perlu diperhatikan saat pendampingan.'}}
function demo(){
const students=Array.from({length:12},(_,i)=>child('SIM-'+String(i+1).padStart(3,'0'),i<6?'7A':'7B'));
students[3].strength='Berminat pada praktik langsung dan kegiatan kelompok kecil.';
students[7].strength='Antusias saat kegiatan menggambar dan kerja kelompok.';
const o=(id,ch,days,area,indicator,context,prior,behavior,impact,response,strength,urgent=false)=>({id,childId:ch,date:dayAgo(days),area,indicator,context,prior,behavior,impact,response,strength,occurrence:'Satu kejadian tercatat',duration:'',author:'Guru kelas',urgent});
const observations=[
 o('OBS-001','SIM-004',13,'BL','BL01','Latihan mandiri Matematika','Guru membagikan latihan berisi lima soal.','Siswa berpindah tempat dua kali selama latihan.','Tiga soal belum dikerjakan saat waktu latihan selesai.','Guru membagi tugas menjadi dua bagian dan menjelaskan langkah pertama.','Siswa mulai mengerjakan ketika tugas dibagi.'),
 o('OBS-002','SIM-004',11,'BL','BL01','Menulis laporan kelompok','Siswa diminta menyalin hasil diskusi.','Siswa berhenti menulis beberapa kali dan menanyakan instruksi ulang.','Bagian laporan belum selesai.','Guru memberikan contoh satu kalimat pembuka.','Siswa dapat melanjutkan dengan contoh.'),
 o('OBS-003','SIM-004',9,'PR','PR01','Diskusi kelompok','Kelompok mulai membagi peran.','Siswa berdiri dan berjalan menuju kelompok lain sebanyak dua kali.','Satu tahap diskusi tertunda.','Guru menyampaikan aturan dan memberikan peran praktis.','Siswa mau membantu menyiapkan alat.'),
 o('OBS-004','SIM-002',8,'ES','ES03','Presentasi kelas','Guru mengundang siswa menyampaikan hasil diskusi.','Siswa mengatakan “saya belum bisa” sebelum mencoba.','Siswa belum memulai presentasi di depan kelas.','Guru menawarkan presentasi berdua.','Siswa mulai berbicara bersama temannya.'),
 o('OBS-005','SIM-008',7,'ES','ES04','Istirahat sekolah','Teman-teman sedang bermain berkelompok.','Siswa memilih duduk sendiri sepanjang satu jam istirahat.','Belum diketahui apakah siswa ingin bergabung.','Guru menyapa dan menawarkan pilihan kegiatan.','Siswa memilih menggambar.'),
 o('OBS-006','SIM-001',6,'BL','BL04','Membaca teks narasi','Guru meminta siswa membaca paragraf pendek.','Siswa meminta waktu tambahan dan mengeja beberapa kata berulang.','Kegiatan membaca membutuhkan waktu lebih panjang.','Guru memberi waktu dan membacakan contoh pertama.','Siswa mengikuti setelah mendapat contoh.'),
 o('OBS-007','SIM-003',5,'BL','BL06','Latihan numerasi','Guru memberi soal penjumlahan dua bilangan.','Siswa beberapa kali tertukar saat menuliskan hasil.','Dua soal memerlukan koreksi bersama.','Guru menggunakan benda konkret.','Siswa dapat menjelaskan jumlah menggunakan benda.'),
 o('OBS-008','SIM-007',4,'PR','PR04','Persiapan pergantian pelajaran','Guru meminta siswa menyiapkan buku berikutnya.','Siswa baru memulai setelah dua pengingat.','Persiapan membutuhkan waktu tambahan.','Guru menunjukkan daftar periksa sederhana.','Siswa berhasil mengambil buku.'),
 o('OBS-009','SIM-011',2,'ES','ES01','Permainan kelompok','Siswa tidak mendapat giliran pertama.','Siswa terlihat menangis dan menjauh dari kelompok.','Siswa berhenti mengikuti permainan.','Guru memberi waktu tenang dan mendengarkan penjelasan siswa.','Siswa kemudian kembali berpartisipasi.')
];
const plans=[
 {id:'SUP-001',childId:'SIM-004',action:'Instruksi bertahap dengan contoh konkret dan daftar cek kegiatan belajar.',owner:'Guru kelas',startDate:dayAgo(10),reviewDate:dayAhead(3),status:'ongoing',result:'Respons awal: mulai bekerja ketika langkah dibagi.',observationId:'OBS-001'},
 {id:'SUP-002',childId:'SIM-002',action:'Latihan presentasi dalam kelompok kecil dan umpan balik positif.',owner:'Wali kelas',startDate:dayAgo(7),reviewDate:dayAhead(5),status:'ongoing',result:'Mau mencoba presentasi berdua.',observationId:'OBS-004'},
 {id:'SUP-003',childId:'SIM-008',action:'Ajak berbincang untuk memahami pilihan aktivitas saat istirahat tanpa memaksa interaksi.',owner:'Guru BK',startDate:dayAgo(5),reviewDate:dayAhead(7),status:'planned',result:'',observationId:'OBS-005'},
 {id:'SUP-004',childId:'SIM-003',action:'Latihan penjumlahan dengan benda konkret secara bertahap.',owner:'Guru Matematika',startDate:dayAgo(4),reviewDate:dayAgo(1),status:'review',result:'Perlu meninjau hasil latihan berikutnya.',observationId:'OBS-007'}
];
return {students,observations,plans};
}
function load(){try{const s=sessionStorage.getItem(STORAGE);if(s){const obj=JSON.parse(s);if(obj&&Array.isArray(obj.students)&&Array.isArray(obj.observations)&&Array.isArray(obj.plans))return obj}}catch(e){console.warn('Penyimpanan sesi tidak tersedia, menggunakan memori halaman.')};return demo()}
let data=load();
let state={view:'home',student:'SIM-004',reportStudent:'SIM-004',obsFilter:'',studentFilter:'',signalsTab:'summary',editingObs:null,editingPlan:null,editingChild:null,mobile:false,safetyShown:false};
const byChild=id=>data.observations.filter(x=>x.childId===id).sort((a,b)=>b.date.localeCompare(a.date));
const plansChild=id=>data.plans.filter(x=>x.childId===id);
const getStudent=id=>data.students.find(s=>s.id===id)||data.students[0];
const countsByArea=(o)=>Object.keys(AREAS).map(k=>({key:k,count:o.filter(v=>v.area===k).length}));
function save(silent=false){try{sessionStorage.setItem(STORAGE,JSON.stringify(data));return true}catch(e){if(!silent)notify('Penyimpanan sesi tidak tersedia; data hanya ada sampai halaman ditutup.');return false}}
function notify(msg){const t=document.getElementById('toast');t.textContent=msg;t.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>{t.hidden=true},4400)}
function optsStudents(selected,all=false){return (all?'<option value="all">Semua kode anak</option>':'')+data.students.map(s=>`<option value="${esc(s.id)}" ${s.id===selected?'selected':''}>${esc(s.code)} • Kelas ${esc(s.klass)}</option>`).join('')}
function areaOptions(v){return Object.entries(AREAS).map(([k,a])=>`<option value="${k}" ${k===v?'selected':''}>${esc(a.name)}</option>`).join('')}
function indicators(area,selected){return Object.entries(IND).filter(([key])=>key.startsWith(area)).map(([key,label])=>`<option value="${key}" ${key===selected?'selected':''}>${key} — ${esc(label)}</option>`).join('')}
function disclaimer(){return `<div class="notice" role="note"><div class="mark" aria-hidden="true">!</div><div><strong>PENTING — BUKAN ALAT DIAGNOSIS PSIKOLOGIS</strong><p>${esc(LONG_NOTICE)}</p></div></div>`}
function modeBanner(){return `<div class="mode-note"><strong>MODE SIMULASI — SELURUH DATA FIKTIF.</strong> Data latihan berada pada sesi tab browser ini; tidak dikirim ke Edumind oleh aplikasi. Jangan memasukkan identitas atau catatan anak nyata. Penyimpanan browser pada domain bersama tidak menjamin kerahasiaan.</div>`}
function shell(){const navKey=state.view==='observation-form'?'observations':state.view==='plan-form'?'supports':state.view==='child-form'?'students':state.view;
return `<div class="mobile-backdrop ${state.mobile?'open':''}" data-action="close-menu" aria-hidden="true"></div><div class="app-shell"><aside class="sidebar ${state.mobile?'open':''}" id="app-navigation"><div class="brand"><img class="brand-logo" src="${BRAND_LOGO}" alt="Edumind Academy"></div><div class="product-label">PEMETAAN SINYAL<br>PSIKOLOGIS ANAK</div><nav class="nav-items" aria-label="Menu utama">${MENU.map(([key,label,ic],i)=>`<button type="button" data-action="navigate" data-target="${key}" class="nav-btn ${navKey===key?'active':''}" ${navKey===key?'aria-current="page"':''}><span class="nav-idx">${String(i+1).padStart(2,'0')}</span>${svg(ic)}<span>${esc(label)}</span></button>`).join('')}</nav><div class="nav-bottom">${esc(DISCLAIMER)}<br><br>V1.0 DEMO · Checkpoint C<br>Hanya untuk data simulasi.</div></aside><div class="main-wrap"><div class="main-inner"><header class="topbar"><div><button type="button" class="top-button mobile-menu" data-action="toggle-menu" aria-label="Buka menu">☰ Menu</button><div class="school-name">Sekolah Contoh Edumind — SIMULASI FIKTIF</div><div class="tiny">Demo pengamatan pendidikan · Tanpa akun dan tanpa server</div></div><div class="top-actions"><span class="sim-badge">● DATA FIKTIF</span><button type="button" class="top-button" data-action="navigate" data-target="guides">Panduan</button><button type="button" class="top-button" data-action="clear">Kosongkan data</button><button type="button" class="top-button" data-action="reset">Atur ulang demo</button></div></header>${disclaimer()}${modeBanner()}<main id="main-content">${renderView()}</main><footer class="footer">Edumind Academy · Checkpoint C V1.0 Demo · Catatan bersifat pendidikan dan tidak menetapkan diagnosis. Materi utama: pemaparan Trubus Raharjo mengenai perilaku siswa dan strategi pendampingan. Tidak digunakan untuk data anak nyata.</footer></div></div></div>`;
}
function title(t,desc='',action=''){return `<div class="title-row"><div><h1 class="page-title">${esc(t)}</h1>${desc?`<p class="page-sub">${esc(desc)}</p>`:''}</div>${action?`<div class="title-actions">${action}</div>`:''}</div>`}
function btn(label,action,cls='btn',extras=''){return `<button type="button" class="${cls}" data-action="${action}" ${extras}>${label}</button>`}
function card(body,extra=''){return `<section class="card ${extra}">${body}</section>`}
function chartRows(observations){const cs=countsByArea(observations),max=Math.max(1,...cs.map(x=>x.count));return `<div class="chart-rows">${cs.map(x=>`<div class="chart-row"><span>${esc(AREAS[x.key].short)}</span><div class="bar-track" role="img" aria-label="${esc(AREAS[x.key].name)}: ${x.count} catatan"><div class="bar-fill" style="width:${x.count/max*100}%"></div></div><strong>${x.count}</strong></div>`).join('')}</div><p class="search-note">Panjang batang = jumlah catatan, bukan skor atau persentase risiko.</p>`}
function home(){const open=data.plans.filter(x=>x.status!=='done').length;const due=data.plans.filter(x=>x.status!=='done'&&x.reviewDate<=dayAhead(7)).length;const latest=[...data.observations].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
return title('Pendampingan yang terarah','Mulai dari pengamatan faktual, bukan pelabelan anak.',btn('+ Catat observasi','new-observation','btn primary'))+`<div class="grid stats"><div class="stat"><div class="lbl">Profil contoh</div><div class="number">${data.students.length}</div><div class="tiny">Seluruhnya fiktif</div></div><div class="stat"><div class="lbl">Catatan observasi</div><div class="number">${data.observations.length}</div><div class="tiny">Rekaman simulasi</div></div><div class="stat"><div class="lbl">Dukungan belum selesai</div><div class="number">${open}</div><div class="tiny">Status administratif</div></div><div class="stat"><div class="lbl">Peninjauan ≤ 7 hari/terlewat</div><div class="number">${due}</div><div class="tiny">Bukan tingkat risiko</div></div></div><div class="grid two">${card(`<div class="card-head"><div><h3>Catatan observasi terbaru</h3><div class="tiny">Berbasis kejadian yang benar-benar tercatat</div></div>${btn('Lihat semua','navigate','btn small','data-target="observations"')}</div>${latest.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Kode anak</th><th>Area / indikator</th><th>Aksi</th></tr></thead><tbody>${latest.map(o=>`<tr><td>${fdate(o.date)}</td><td>${esc(o.childId)}</td><td>${esc(AREAS[o.area]?.short||'')}<div class="tiny">${esc(IND[o.indicator]||'')}</div></td><td>${btn('Lihat','view-child','btn small',`data-id="${esc(o.childId)}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada observasi. Tidak berarti anak tidak memiliki kesulitan.</div>'}`)}${card(`<h3>Rekap area observasi</h3><div class="tiny">Jumlah entri per kelompok pada data latihan</div>${chartRows(data.observations)}${btn('Buka Peta Sinyal →','navigate','btn','data-target="signals"')}`)}</div><div class="grid two" style="margin-top:14px">${card(`<h3>Tindak lanjut terdekat</h3><div class="tiny">Ditentukan dan diperiksa manusia</div><div class="timeline">${data.plans.filter(p=>p.status!=='done').sort((a,b)=>a.reviewDate.localeCompare(b.reviewDate)).slice(0,4).map(p=>`<div class="time-item"><div class="time-meta">${esc(p.childId)} · Tinjau ${fdate(p.reviewDate)}</div><div class="time-title">${esc(p.action)}</div><span class="pill ${p.status==='review'?'amber':'green'}">${LABEL_STATUS[p.status]||'Ditinjau'}</span></div>`).join('')||'<div class="empty">Belum ada rencana pendampingan.</div>'}</div>`)}${card(`<h3>Prinsip membaca hasil</h3><p class="muted">Satu perilaku dapat mempunyai banyak konteks. Guru mencatat yang tampak, menanyakan informasi yang belum diketahui, dan menguji apakah dukungan pendidikan membantu.</p><div class="help-strip"><b>Belum ada data ≠ tidak ada masalah.</b><br>Jumlah catatan yang lebih banyak juga tidak otomatis berarti tingkat gangguan lebih berat.</div><div class="warning-strip"><b>Keselamatan lebih utama.</b><br>Bila ada dugaan kekerasan, ancaman, atau bahaya segera, ikuti prosedur perlindungan anak dan cari bantuan yang tepat, tanpa menunggu skor atau jumlah observasi.</div>${btn('Baca panduan dan prosedur','navigate','btn','data-target="guides"')}`)}</div>`}
function students(){const q=state.studentFilter.toLowerCase().trim();const arr=data.students.filter(s=>`${s.code} ${s.klass}`.toLowerCase().includes(q));return title('Data Anak','Gunakan kode contoh, bukan identitas anak sungguhan.',btn('+ Tambah profil fiktif','new-child','btn primary'))+card(`<div class="toolbar"><div class="field" style="flex:1"><label for="child-search">Cari kode / kelas</label><input id="child-search" placeholder="Contoh: SIM-004 atau 7A" value="${esc(state.studentFilter)}"></div><div class="search-note">${arr.length} profil ditampilkan</div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Kode siswa</th><th>Kelas</th><th>Observasi</th><th>Dukungan</th><th>Aksi</th></tr></thead><tbody>${arr.map(s=>`<tr><td><b>${esc(s.code)}</b><div class="tiny">Profil simulasi</div></td><td>${esc(s.klass)}</td><td>${byChild(s.id).length} catatan</td><td>${plansChild(s.id).length} rencana</td><td class="td-actions">${btn('Peta','view-child','btn small',`data-id="${s.id}"`)} ${btn('Ubah','edit-child','btn small',`data-id="${s.id}"`)} ${btn('Hapus','delete-child','btn danger small',`data-id="${s.id}"`)}</td></tr>`).join('')}</tbody></table></div>${arr.length?'':'<div class="empty">Belum ditemukan.</div>'}`)+`<div class="help-strip">Semua siswa adalah profil kode simulasi. Jangan masukkan nama, tanggal lahir, alamat, atau data sensitif anak sesungguhnya.</div>`}
function childForm(){const x=state.editingChild?getStudent(state.editingChild):null;return title(x?'Ubah profil fiktif':'Tambah profil fiktif','Data contoh hanya untuk latihan.')+`<form id="child-form">${card(`<div class="form-grid"><div class="field"><label for="child-code">Kode unik siswa contoh <span class="req">*</span></label><input id="child-code" name="code" required maxlength="24" pattern="[A-Za-z0-9-]+" placeholder="Misalnya SIM-013" value="${esc(x?.code||'')}" ${x?'readonly':''}><small>${x?'Kode dikunci agar catatan tetap tertaut.':'Huruf, angka, dan tanda hubung. Jangan nama asli.'}</small></div><div class="field"><label for="child-class">Kelas/tahap <span class="req">*</span></label><input id="child-class" name="klass" required maxlength="24" placeholder="7A" value="${esc(x?.klass||'')}"></div><div class="field wide"><label for="child-strength">Kekuatan dan minat yang terlihat</label><textarea name="strength" id="child-strength" maxlength="500" placeholder="Contoh: suka menggambar dan merespons baik instruksi visual">${esc(x?.strength||'')}</textarea></div></div><div class="form-footer">${btn('Batal','navigate','btn','data-target="students"')}<button type="submit" class="btn primary">Simpan profil contoh</button></div>`)}</form>`}
function observations(){const q=state.obsFilter;const arr=data.observations.filter(o=>!q||o.childId===q).sort((a,b)=>b.date.localeCompare(a.date));return title('Observasi','Catat kejadian nyata yang tampak pada konteks tertentu—di demo gunakan kejadian fiktif.',btn('+ Catat observasi','new-observation','btn primary'))+card(`<div class="toolbar"><div class="field"><label for="obs-filter">Filter kode anak</label><select id="obs-filter"><option value="">Semua anak</option>${optsStudents(q)}</select></div><div class="search-note">${arr.length} observasi tercatat</div></div>${arr.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Kode</th><th>Area / indikator</th><th>Kegiatan / pengamatan</th><th>Aksi</th></tr></thead><tbody>${arr.map(o=>`<tr><td>${fdate(o.date)}</td><td><b>${esc(o.childId)}</b></td><td>${esc(AREAS[o.area]?.short||'')}<br><span class="tiny">${esc(IND[o.indicator]||'')}</span></td><td>${esc(o.context)}<div class="tiny">${esc(o.behavior.slice(0,85))}${o.behavior.length>85?'…':''}</div>${o.urgent?'<span class="pill red">Perlu prosedur keselamatan</span>':''}</td><td class="td-actions">${btn('Ubah','edit-observation','btn small',`data-id="${esc(o.id)}"`)} ${btn('Hapus','delete-observation','btn danger small',`data-id="${esc(o.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada catatan. Ini bukan pernyataan kondisi anak.</div>'}`)+`<div class="help-strip"><b>Pedoman:</b> tulis “siswa bangkit dari kursi dua kali”, bukan “siswa ADHD”. Catat konteks, respons dan kekuatan anak.</div>`}
function obsForm(){const o=state.editingObs?data.observations.find(x=>x.id===state.editingObs):null;const area=o?.area||'BL';return title(o?'Ubah catatan observasi':'Tambah catatan observasi','Observasi pendidikan — bukan instrumen diagnosis.')+`<form id="observation-form"><div class="form-section"><h3>1. Informasi dasar</h3><div class="form-grid"><div class="field"><label for="obs-child">Kode anak <span class="req">*</span></label><select id="obs-child" name="childId" required>${optsStudents(o?.childId||state.student)}</select></div><div class="field"><label for="obs-date">Tanggal observasi <span class="req">*</span></label><input id="obs-date" type="date" name="date" required value="${esc(o?.date||iso())}"></div><div class="field wide"><label for="obs-context">Kegiatan / lokasi / situasi <span class="req">*</span></label><input id="obs-context" name="context" required maxlength="180" placeholder="Contoh: latihan Matematika di kelas" value="${esc(o?.context||'')}"></div></div></div><div class="form-section"><h3>2. Area dan indikator pengamatan</h3><div class="form-grid"><div class="field"><label for="obs-area">Kelompok observasi <span class="req">*</span></label><select id="obs-area" name="area" required>${areaOptions(area)}</select></div><div class="field"><label for="obs-indicator">Indikator deskriptif <span class="req">*</span></label><select id="obs-indicator" name="indicator" required>${indicators(area,o?.indicator)}</select></div></div></div><div class="form-section"><h3>3. Catatan faktual dan konteks</h3><div class="form-grid"><div class="field"><label for="obs-prior">Apa yang terjadi sebelumnya? <span class="req">*</span></label><textarea id="obs-prior" name="prior" required maxlength="1500" placeholder="Instruksi, kegiatan atau situasi yang mendahului">${esc(o?.prior||'')}</textarea></div><div class="field"><label for="obs-behavior">Apa yang benar-benar terlihat/terdengar? <span class="req">*</span></label><textarea id="obs-behavior" name="behavior" required maxlength="1500" placeholder="Catatan perilaku atau ucapan anak, bukan dugaan diagnosis">${esc(o?.behavior||'')}</textarea></div><div class="field"><label for="obs-impact">Dampak terhadap kegiatan</label><textarea id="obs-impact" name="impact" maxlength="800" placeholder="Dampak yang terlihat, jika diketahui">${esc(o?.impact||'')}</textarea></div><div class="field"><label for="obs-response">Dukungan yang dicoba dan respons anak</label><textarea id="obs-response" name="response" maxlength="1000" placeholder="Apa yang guru lakukan? Bagaimana respons anak?">${esc(o?.response||'')}</textarea></div><div class="field wide"><label for="obs-strength">Kekuatan, minat atau kondisi yang membantu <span class="req">*</span></label><textarea id="obs-strength" name="strength" required maxlength="900" placeholder="Catat keberhasilan sekecil apa pun dan situasi yang membantu">${esc(o?.strength||'')}</textarea></div><div class="field"><label for="obs-occurrence">Frekuensi yang benar-benar dicatat</label><select id="obs-occurrence" name="occurrence">${['Belum diketahui','Satu kejadian tercatat','Dua kejadian tercatat','Tiga kejadian atau lebih tercatat'].map(v=>`<option ${v===(o?.occurrence||'Belum diketahui')?'selected':''}>${v}</option>`).join('')}</select><small>Jangan menebak frekuensi jika belum diamati.</small></div><div class="field"><label for="obs-duration">Durasi (bila diketahui)</label><input id="obs-duration" name="duration" maxlength="80" placeholder="Contoh: sekitar 4 menit" value="${esc(o?.duration||'')}"></div><div class="field"><label for="obs-author">Peran pencatat <span class="req">*</span></label><select id="obs-author" name="author" required>${['Guru kelas','Wali kelas','Guru BK','Guru mata pelajaran','Koordinator'].map(x=>`<option ${x===(o?.author||'Guru kelas')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="obs-urgent">Catatan keselamatan</label><label class="choice" for="obs-urgent"><input id="obs-urgent" type="checkbox" name="urgent" ${o?.urgent?'checked':''}> Ada indikasi situasi yang memerlukan prosedur keselamatan anak</label></div></div><div class="warning-strip">Jika ada ancaman, kekerasan, atau bahaya segera, prioritaskan perlindungan dan pertolongan sesuai prosedur sekolah. Jangan menunggu kelengkapan form, pola berulang atau skor.</div></div><div class="form-footer">${btn('Batal','navigate','btn','data-target="observations"')}<button type="submit" class="btn primary">Simpan observasi fiktif</button></div></form>`}
function signalSummary(s,obs){const areaCounts=countsByArea(obs),countIndicator={};obs.forEach(o=>countIndicator[o.indicator]=(countIndicator[o.indicator]||0)+1);const lines=Object.entries(countIndicator).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...lines.map(x=>x[1]));return `<div class="grid two">${card(`<h3>Gambaran umum</h3><p class="muted">${obs.length} catatan observasi pada profil ini. Semua kesimpulan memerlukan peninjauan konteks oleh pendidik.</p><div class="help-strip"><b>Peta ini bukan tes psikologi.</b><br>Tidak memberikan label atau diagnosis.</div><div class="report-grid"><div><b>${obs.length}</b><span class="tiny">Catatan</span></div><div><b>${new Set(obs.map(x=>x.date)).size}</b><span class="tiny">Hari berbeda</span></div><div><b>${plansChild(s.id).length}</b><span class="tiny">Rencana</span></div></div>`)}${card(`<h3>Area yang tercatat</h3>${obs.length?chartRows(obs):'<div class="empty">Belum ada data observasi; bukan berarti tidak ada kebutuhan.</div>'}<p class="tiny">Area ditentukan oleh kategori formulir yang dipilih guru.</p>`)}</div><div class="grid two" style="margin-top:14px">${card(`<h3>Rincian indikator tercatat</h3>${lines.length?`<div class="signal-list">${lines.map(([code,n])=>`<div class="signal-line"><div><span class="signal-dot"></span>${esc(IND[code]||code)}</div><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><b>${n} catatan</b></div>`).join('')}</div>`:'<div class="empty">Belum ada indikator yang tercatat.</div>'}<div class="tiny">Jumlah catatan, bukan besarnya masalah atau peluang diagnosis.</div>`,'strength-card')}${card(`<h3>Kekuatan dan respons yang membantu</h3><p class="muted">${esc(s.strength||'Belum dicatat.')}</p>${obs.length?`<ul>${obs.slice(0,4).map(x=>`<li>${esc(x.strength||x.response||'Belum dicatat')}</li>`).join('')}</ul>`:'<p class="muted">Lengkapi melalui catatan observasi.</p>'}<div class="help-strip">Penetapan dukungan dilakukan guru dan sekolah dengan mempertimbangkan suara anak dan keluarga.</div>`,'support-card')}</div>`}
function signalTimeline(obs){return card(`<h3>Garis waktu observasi</h3>${obs.length?`<div class="timeline">${obs.map(o=>`<div class="time-item"><div class="time-meta">${fdate(o.date)} · ${esc(o.context)} · ${esc(o.author)}</div><div class="time-title">${esc(IND[o.indicator]||o.indicator)}</div><div class="info-pair"><div class="key">Sebelum</div><div>${esc(o.prior)}</div><div class="key">Teramati</div><div>${esc(o.behavior)}</div><div class="key">Dukungan</div><div>${esc(o.response||'Belum dicatat')}</div><div class="key">Kekuatan</div><div>${esc(o.strength||'Belum dicatat')}</div></div>${o.urgent?'<div class="app-alert"><b>Catatan keselamatan:</b> ikuti prosedur perlindungan sekolah; jangan menunggu skor.</div>':''}</div>`).join('')}</div>`:'<div class="empty">Belum ada catatan observasi.</div>'}`)}
function signals(){const s=getStudent(state.student);if(!s)return title('Peta Sinyal','Tambahkan profil contoh dahulu.');const obs=byChild(s.id);const pc=plansChild(s.id);return title('Peta Sinyal','Pola dari observasi pendidikan yang tercatat, bukan hasil asesmen klinis.',btn('+ Catat observasi','new-observation','btn primary'))+`<div class="toolbar"><div class="field"><label for="signal-child">Kode anak contoh</label><select id="signal-child">${optsStudents(s.id)}</select></div></div>${card(`<div class="student-header"><div class="avatar" aria-hidden="true">${esc(s.code.slice(-2))}</div><div><h3 style="margin:0">${esc(s.code)} · Kelas ${esc(s.klass)}</h3><div class="tiny">Identitas dibuat untuk simulasi · ${obs.length} catatan tercatat</div></div></div><div class="tabs" role="tablist" aria-label="Rincian Peta Sinyal">${[['summary','Ringkasan'],['timeline','Catatan & riwayat'],['supports','Pendampingan']].map(([id,label])=>`<button type="button" role="tab" aria-selected="${state.signalsTab===id?'true':'false'}" data-action="signal-tab" data-id="${id}" class="tab ${state.signalsTab===id?'active':''}">${label}</button>`).join('')}</div><div class="help-strip"><b>Alat bantu observasi dan pemetaan awal. Bukan alat diagnosis psikologis.</b> Indikator menunjukkan catatan yang dipilih guru, bukan skor risiko anak.</div>${state.signalsTab==='summary'?signalSummary(s,obs):state.signalsTab==='timeline'?signalTimeline(obs):`<h3>Rencana dukungan ${esc(s.code)}</h3>${supportTable(pc)}${btn('+ Tambah rencana','new-plan','btn primary')}`}`)}`}
function supportTable(plans){return plans.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Kode</th><th>Rencana tindakan</th><th>Penanggung jawab</th><th>Tinjau</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${plans.map(p=>`<tr><td>${esc(p.childId)}</td><td>${esc(p.action)}${p.result?`<div class="tiny">Hasil: ${esc(p.result)}</div>`:''}</td><td>${esc(p.owner)}</td><td>${fdate(p.reviewDate)}</td><td><span class="pill ${p.status==='done'?'green':p.status==='review'?'amber':'blue'}">${esc(LABEL_STATUS[p.status]||p.status)}</span></td><td class="td-actions">${btn('Ubah','edit-plan','btn small',`data-id="${esc(p.id)}"`)} ${btn('Hapus','delete-plan','btn danger small',`data-id="${esc(p.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada rencana. Pendampingan ditetapkan oleh guru/pihak berwenang, bukan otomatis.</div>'}
function supports(){return title('Pendampingan','Tindakan, penanggung jawab, dan jadwal peninjauan ditentukan oleh pendidik.',btn('+ Buat rencana','new-plan','btn primary'))+card(`<h3>Rencana dan tindak lanjut</h3><div class="tiny" style="margin-bottom:12px">Status adalah status pekerjaan, bukan kesimpulan kondisi psikologis anak.</div>${supportTable([...data.plans].sort((a,b)=>a.reviewDate.localeCompare(b.reviewDate)))}`)+`<div class="help-strip">Pilihan dukungan berfokus pada akses belajar, interaksi aman, koordinasi keluarga dan rujukan sesuai kewenangan. Aplikasi tidak memberi resep, terapi klinis, atau diagnosis.</div>`}
function planForm(){const p=state.editingPlan?data.plans.find(x=>x.id===state.editingPlan):null;return title(p?'Ubah rencana dukungan':'Tambah rencana pendampingan','Tentukan tindakan pendidikan yang aman dan bisa dievaluasi.')+`<form id="plan-form">${card(`<div class="form-grid"><div class="field"><label for="plan-child">Kode anak <span class="req">*</span></label><select id="plan-child" name="childId">${optsStudents(p?.childId||state.student)}</select></div><div class="field"><label for="plan-obs">Rujukan catatan observasi</label><select id="plan-obs" name="observationId"><option value="">Tidak dipilih</option>${data.observations.map(o=>`<option value="${esc(o.id)}" ${o.id===p?.observationId?'selected':''}>${esc(o.id)} · ${esc(o.childId)} · ${esc(IND[o.indicator]||'')}</option>`).join('')}</select><small>Hanya catatan pada anak yang sama akan diterima saat disimpan.</small></div><div class="field wide"><label for="plan-action">Tindakan pendampingan <span class="req">*</span></label><textarea id="plan-action" name="action" required maxlength="1500" placeholder="Contoh: berikan instruksi singkat bertahap lalu tinjau respons siswa">${esc(p?.action||'')}</textarea></div><div class="field"><label for="plan-owner">Penanggung jawab <span class="req">*</span></label><select id="plan-owner" name="owner">${['Guru kelas','Wali kelas','Guru BK','Guru Matematika','Guru Bahasa Indonesia','Koordinator'].map(x=>`<option ${x===(p?.owner||'Guru kelas')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="plan-status">Status administratif</label><select id="plan-status" name="status">${Object.entries(LABEL_STATUS).map(([k,v])=>`<option value="${k}" ${k===(p?.status||'planned')?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="plan-start">Tanggal mulai <span class="req">*</span></label><input id="plan-start" type="date" name="startDate" required value="${esc(p?.startDate||iso())}"></div><div class="field"><label for="plan-review">Tanggal tinjau <span class="req">*</span></label><input id="plan-review" type="date" name="reviewDate" required value="${esc(p?.reviewDate||dayAhead(7))}"></div><div class="field wide"><label for="plan-result">Hasil peninjauan / respons anak</label><textarea id="plan-result" name="result" maxlength="1500" placeholder="Catat hasil yang teramati. Kosong jika belum ditinjau.">${esc(p?.result||'')}</textarea></div></div><div class="form-footer">${btn('Batal','navigate','btn','data-target="supports"')}<button type="submit" class="btn primary">Simpan rencana fiktif</button></div>`)}</form>`}
function reports(){const s=getStudent(state.reportStudent);if(!s)return title('Laporan','Tidak ada profil contoh.');const obs=byChild(s.id),plans=plansChild(s.id),counts=countsByArea(obs);const report=`<section class="card report-doc" id="report-paper"><div class="only-print">EDUMIND ACADEMY · MODE SIMULASI</div><div class="report-title">Laporan Observasi Pendidikan — SIMULASI</div><div class="tiny">${esc(DISCLAIMER)} · Dicetak ${fdate(iso())}</div><div class="report-grid"><div><span class="tiny">Kode anak</span><b>${esc(s.code)}</b></div><div><span class="tiny">Kelas contoh</span><b>${esc(s.klass)}</b></div><div><span class="tiny">Catatan</span><b>${obs.length}</b></div></div><h3>Rekap jumlah catatan</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Area</th><th>Catatan</th><th>Batas interpretasi</th></tr></thead><tbody>${counts.map(x=>`<tr><td>${esc(AREAS[x.key].name)}</td><td>${x.count}</td><td>Jumlah catatan yang tersedia; bukan besarnya gangguan.</td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:19px">Kekuatan anak dan dukungan yang membantu</h3><p>${esc(s.strength||'Belum dicatat')}</p><ul>${obs.slice(0,5).map(o=>`<li>${esc(o.strength||o.response||'Belum dicatat')}</li>`).join('')||'<li>Belum ada catatan.</li>'}</ul><h3>Rangkuman observasi per kejadian</h3>${obs.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Situasi</th><th>Yang teramati</th><th>Dukungan / respons</th></tr></thead><tbody>${obs.map(o=>`<tr><td>${fdate(o.date)}</td><td>${esc(o.context)}</td><td>${esc(o.behavior)}</td><td>${esc(o.response||'Belum dicatat')}</td></tr>`).join('')}</tbody></table></div>`:'<p>Belum ada observasi. Ini tidak berarti siswa tidak memiliki kesulitan.</p>'}<h3 style="margin-top:19px">Rencana pendampingan</h3>${plans.length?`<ol>${plans.map(p=>`<li>${esc(p.action)} — ${esc(p.owner)} (tinjau ${fdate(p.reviewDate)}, ${esc(LABEL_STATUS[p.status]||'')})</li>`).join('')}</ol>`:'<p>Belum ada rencana pendampingan.</p>'}<div class="report-legal app-alert"><b>PERNYATAAN WAJIB:</b> ${esc(LONG_NOTICE)}<br><b>Dokumen ini merupakan simulasi observasi pendidikan, bukan hasil tes psikologi dan tidak dapat digunakan sebagai surat keterangan diagnosis.</b></div><div class="tiny">Seluruh kode, kejadian dan hasil pada contoh ini fiktif. Tidak ada pengiriman data otomatis.</div></section>`;
return title('Laporan','Buat dan cetak ringkasan deskriptif yang memuat batasan penggunaan.',btn('Cetak / Simpan PDF','print-report','btn primary')+btn('Unduh CSV rekap anonim','export-csv','btn'))+`<div class="toolbar hide-print"><div class="field"><label for="report-child">Profil contoh</label><select id="report-child">${optsStudents(s.id)}</select></div></div>${report}`}
function guides(){return title('Panduan & Edukasi','Pedoman observasi yang mendukung strategi pendampingan siswa.')+`<div class="grid two">${card(`<h3>Langkah penggunaan</h3><ol><li>Pilih profil siswa <b>fiktif</b>.</li><li>Masuk Observasi dan catat satu kejadian.</li><li>Jelaskan situasi sebelum dan perilaku yang benar-benar terlihat.</li><li>Catat kekuatan anak dan bantuan yang sudah dicoba.</li><li>Buka Peta Sinyal; periksa jumlah dan konteks catatan.</li><li>Tentukan tindakan pendampingan secara manusiawi.</li><li>Tinjau perkembangan dan buat laporan simulasi.</li></ol><p class="muted">Gunakan kategori belajar, perilaku/pengaturan diri, serta emosional/psikososial sebagai panduan pencatatan, bukan kategori penyakit.</p>`)}${card(`<h3>Pemisahan observasi dan diagnosis</h3><div class="help-strip"><b>${esc(DISCLAIMER)}</b></div><ul><li>Hindari menulis label seperti “ADHD”, “disleksia” atau “gangguan kecemasan” sebagai hasil otomatis.</li><li>Satu kejadian tidak membuktikan sebab, sifat menetap, atau kondisi klinis.</li><li>“Belum ada data” bukan berarti anak tidak memerlukan bantuan.</li><li>Kebutuhan dan kekuatan anak dibaca bersama dengan konteks, bukan sekadar angka.</li><li>Bila diperlukan pemeriksaan klinis, konsultasikan kepada profesional berwenang.</li></ul>`)}${card(`<h3>Contoh bahasa yang dianjurkan</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Hindari</th><th>Catatan faktual</th></tr></thead><tbody><tr><td>“Siswa hiperaktif/ADHD.”</td><td>“Siswa berpindah tempat dua kali saat kegiatan menulis.”</td></tr><tr><td>“Siswa pemalas.”</td><td>“Siswa belum memulai tugas setelah instruksi diberikan; perlu klarifikasi hambatan.”</td></tr><tr><td>“Siswa mengalami disleksia.”</td><td>“Siswa meminta waktu tambahan saat mengeja kata pada kegiatan membaca.”</td></tr><tr><td>“Siswa antisosial.”</td><td>“Siswa memilih menggambar sendiri saat waktu istirahat.”</td></tr></tbody></table></div>`)}${card(`<h3>Keselamatan dan rujukan</h3><ul class="safety-list"><li>Jika ada dugaan kekerasan/perundungan atau ancaman keselamatan, utamakan perlindungan sesuai SOP sekolah.</li><li>Hubungi penanggung jawab perlindungan anak dan bantuan profesional/layanan darurat setempat sesuai kebutuhan.</li><li>Jangan melakukan interogasi, menyebarluaskan catatan atau menjanjikan kerahasiaan mutlak.</li><li>Komunikasikan kepada orang tua/wali sesuai prosedur dan kepentingan terbaik anak.</li><li>Aplikasi tidak menetapkan pengobatan, diet atau terapi klinis.</li></ul><div class="warning-strip">Ketika keselamatan terancam, tindak lanjuti segera; jangan menunggu jumlah catatan atau hasil peta.</div>`)}${card(`<h3>Dasar materi webinar</h3><p>Pemaparan <b>Trubus Raharjo</b>, “Memahami Akar Masalah Perilaku Siswa dan Strategi Pendampingan”. Pokok pembahasan: perilaku tampak, kesulitan belajar, perilaku/pengaturan diri, keadaan emosional/psikososial dan strategi pendampingan.</p><p class="muted">Indikator merupakan pengembangan operasional Edumind untuk observasi pendidikan, bukan instrumen psikometrik tervalidasi. Panduan tambahan tentang keamanan anak, bahasa faktual, privasi, dan rujukan disusun untuk kehati-hatian, bukan pernyataan baru narasumber.</p>`)}${card(`<h3>Privasi dan mode demonstrasi</h3><ul><li>Semua data awal fiktif, diberi kode SIM.</li><li>Catatan demo disimpan di <b>sessionStorage</b> pada tab browser bila tersedia; bukan database server.</li><li>Data bertahan selama tab/sesi tersedia, termasuk setelah reload; tombol Atur ulang mengembalikan data contoh.</li><li>Jangan masukkan data siswa nyata. Tidak ada akun, sinkronisasi, atau enkripsi lintas pengguna.</li><li>Unduhan CSV berisi rekap hitungan anonim per kelompok dan tanpa nama siswa.</li><li>Gunakan server dan kontrol akses yang diaudit untuk penggunaan operasional.</li></ul>${btn('Atur ulang data simulasi','reset','btn danger')}`)}</div>`}
function renderView(){switch(state.view){case 'students':return students();case 'child-form':return childForm();case 'observations':return observations();case 'observation-form':return obsForm();case 'signals':return signals();case 'supports':return supports();case 'plan-form':return planForm();case 'reports':return reports();case 'guides':return guides();default:return home()}}
function render(){const root=document.getElementById('app');root.innerHTML=shell();document.body.dataset.printView=state.view==='reports'?'report':'';}
function go(view){if(!MENU.some(x=>x[0]===view)&&!['observation-form','plan-form','child-form'].includes(view))view='home';state.view=view;state.mobile=false;render();window.scrollTo({top:0,behavior:'instant'});}
function confirmAction(t){return window.confirm(t)}
function safeText(v){return String(v||'').trim()}
function onAction(ev){const target=ev.target.closest('[data-action]');if(!target)return;const a=target.dataset.action,id=target.dataset.id;
if(a==='toggle-menu'){state.mobile=!state.mobile;render();return}if(a==='close-menu'){state.mobile=false;render();return}
if(a==='navigate'){go(target.dataset.target);return}
if(a==='new-child'){state.editingChild=null;go('child-form');return}if(a==='edit-child'){state.editingChild=id;go('child-form');return}
if(a==='delete-child'){const s=getStudent(id);if(!s)return;if(!confirmAction(`Hapus ${s.code} dan seluruh observasi serta dukungan demo yang berkaitan?`))return;data.students=data.students.filter(x=>x.id!==id);data.observations=data.observations.filter(x=>x.childId!==id);data.plans=data.plans.filter(x=>x.childId!==id);state.student=data.students[0]?.id||'';state.reportStudent=state.student;save();render();notify('Profil dan catatan terkait dihapus dari simulasi.');return}
if(a==='new-observation'){if(!data.students.length)return notify('Tambahkan profil contoh terlebih dahulu.');state.editingObs=null;go('observation-form');return}if(a==='edit-observation'){state.editingObs=id;go('observation-form');return}
if(a==='delete-observation'){if(!confirmAction('Hapus catatan observasi fiktif ini?'))return;data.observations=data.observations.filter(x=>x.id!==id);data.plans.forEach(x=>{if(x.observationId===id)x.observationId=''});save();render();notify('Catatan observasi dihapus.');return}
if(a==='view-child'){state.student=id;state.signalsTab='summary';go('signals');return}if(a==='signal-tab'){state.signalsTab=id;render();return}
if(a==='new-plan'){if(!data.students.length)return notify('Tambahkan profil contoh terlebih dahulu.');state.editingPlan=null;go('plan-form');return}if(a==='edit-plan'){state.editingPlan=id;go('plan-form');return}
if(a==='delete-plan'){if(!confirmAction('Hapus rencana pendampingan simulasi ini?'))return;data.plans=data.plans.filter(x=>x.id!==id);save();render();notify('Rencana dihapus.');return}
if(a==='clear'){if(!confirmAction('Kosongkan SELURUH data simulasi di tab ini? Profil, observasi dan rencana akan menjadi kosong. Anda dapat memulihkan contoh melalui Atur ulang demo.'))return;try{sessionStorage.removeItem(STORAGE)}catch(e){};data={students:[],observations:[],plans:[]};state.student='';state.reportStudent='';state.studentFilter='';state.obsFilter='';save(true);go('home');notify('Semua rekaman simulasi telah dikosongkan.');return}
if(a==='reset'){if(!confirmAction('Atur ulang seluruh profil, observasi, dan pendampingan simulasi? Semua perubahan pada tab ini akan diganti dengan data contoh.'))return;try{sessionStorage.removeItem(STORAGE)}catch(e){};data=demo();state.student='SIM-004';state.reportStudent='SIM-004';state.signalsTab='summary';state.obsFilter='';state.studentFilter='';save();go('home');notify('Data latihan dikembalikan ke kondisi awal.');return}
if(a==='print-report'){document.body.dataset.printView='report';window.print();return}
if(a==='export-csv'){exportCsv();return}}
function onSubmit(ev){const form=ev.target;if(!['child-form','observation-form','plan-form'].includes(form.id))return;ev.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);const get=k=>safeText(f.get(k));
if(form.id==='child-form'){
 const code=get('code').toUpperCase();const klass=get('klass');if(!/^[A-Z0-9-]{3,24}$/.test(code))return notify('Kode hanya boleh huruf, angka, dan tanda hubung.');
 if(data.students.some(x=>x.code===code&&x.id!==state.editingChild))return notify('Kode sudah dipakai. Pilih kode lain.');
 if(state.editingChild){const x=data.students.find(x=>x.id===state.editingChild);if(!x)return;x.code=code;x.klass=klass;x.strength=get('strength')}
 else{data.students.push({id:code,code,klass,strength:get('strength')});state.student=code;state.reportStudent=code}
 save();go('students');notify('Profil fiktif berhasil disimpan.');return}
if(form.id==='observation-form'){
 const childId=get('childId');if(!getStudent(childId)||!data.students.some(x=>x.id===childId))return notify('Profil anak contoh tidak ditemukan.');
 const area=get('area'),indicator=get('indicator');if(!(area in AREAS)||!IND[indicator]||!indicator.startsWith(area))return notify('Area dan indikator belum sesuai.');
 const o={id:state.editingObs||uid('OBS'),childId,date:get('date'),area,indicator,context:get('context'),prior:get('prior'),behavior:get('behavior'),impact:get('impact'),response:get('response'),strength:get('strength'),occurrence:get('occurrence'),duration:get('duration'),author:get('author'),urgent:f.has('urgent')};
 if(!o.context||!o.prior||!o.behavior||!o.strength)return notify('Lengkapi konteks, perilaku faktual, dan kekuatan anak.');
 if(state.editingObs){const i=data.observations.findIndex(x=>x.id===state.editingObs);if(i===-1)return;data.observations[i]=o}else data.observations.push(o);
 state.student=childId;save();state.safetyShown=o.urgent;go('observations');notify(o.urgent?'Tersimpan. Utamakan SOP keselamatan anak, jangan menunggu skor.':'Observasi fiktif tersimpan dan Peta Sinyal diperbarui.');return}
if(form.id==='plan-form'){
 const childId=get('childId');if(!data.students.some(s=>s.id===childId))return notify('Kode siswa tidak tersedia.');
 const observationId=get('observationId');if(observationId&&!(data.observations.some(o=>o.id===observationId&&o.childId===childId)))return notify('Rujukan observasi harus berasal dari kode anak yang sama.');
 if(get('reviewDate')<get('startDate'))return notify('Tanggal peninjauan tidak boleh sebelum tanggal mulai.');
 const p={id:state.editingPlan||uid('SUP'),childId,observationId,action:get('action'),owner:get('owner'),status:get('status'),startDate:get('startDate'),reviewDate:get('reviewDate'),result:get('result')};
 if(!p.action)return notify('Lengkapi tindakan pendampingan.');if(!(p.status in LABEL_STATUS))return notify('Status rencana tidak dikenal.');
 if(state.editingPlan){const i=data.plans.findIndex(x=>x.id===state.editingPlan);if(i===-1)return;data.plans[i]=p}else data.plans.push(p);
 state.student=childId;save();go('supports');notify('Rencana pendampingan fiktif berhasil disimpan.');return}}
function onChange(ev){if(ev.target.id==='obs-area'){const area=ev.target.value;const el=document.getElementById('obs-indicator');if(el)el.innerHTML=indicators(area);return}
if(ev.target.id==='signal-child'){state.student=ev.target.value;state.signalsTab='summary';render();return}
if(ev.target.id==='report-child'){state.reportStudent=ev.target.value;render();return}
if(ev.target.id==='obs-filter'){state.obsFilter=ev.target.value;render();return}}
function onInput(ev){if(ev.target.id==='child-search'){state.studentFilter=ev.target.value;const input=ev.target;const cursor=input.selectionStart;render();const next=document.getElementById('child-search');if(next){next.focus();next.setSelectionRange(cursor,cursor)}}}
function exportCsv(){const rows=[['kelompok','jumlah_catatan','keterangan'],...countsByArea(data.observations).map(x=>[AREAS[x.key].name,x.count,'Data fiktif; bukan skor psikologis'])];const csv='\ufeff'+rows.map(r=>r.map(escapeCsv).join(';')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='EDUMIND_REKAP_ANONIM_SIMULASI_'+iso()+'.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV rekap agregat data fiktif dibuat.');}
document.addEventListener('click',onAction);document.addEventListener('submit',onSubmit);document.addEventListener('change',onChange);document.addEventListener('input',onInput);save(true);render();
})();
